def silu(x): return x/(1+np.exp(-x))
def fwd(W,x):
    h=silu(x@W['l1.weight'].T+W['l1.bias'])
    h=silu(h@W['l2.weight'].T+W['l2.bias'])
    return h@W['l3.weight'].T+W['l3.bias']
W={n:load(n) for n in NAMES}
def table(W,s):
    x=np.zeros((1024,68))
    for a in range(32):
        for b in range(32):
            x[a*32+b,a]=1;x[a*32+b,32+b]=1;x[a*32+b,64+s]=1
    return fwd(W,x)
np.set_printoptions(linewidth=250)
for s in range(4):
    T=table(W,s); P=T.argmax(1).reshape(32,32)
    print('skill',s)
    for r in P[:14]: print(' '.join('%2d'%v for v in r[:24]))
    print('conf median',np.median(np.max(T,1)))
    print('uniq',len(np.unique(P)))
