The tables look like op(f(a), g(b)) with hidden 0-7 lookups per skill: skill 0 like max, skill 3 like min, skill 1 like a clipped sum, skill 2 like a product. I will read this off with closed-form estimates (no weight change yet) and compare the current weights with an earlier snapshot.
```python
def silu(x): return x/(1+np.exp(-x))
def fwd(W,x):
    h=silu(x@W['l1.weight'].T+W['l1.bias'])
    h=silu(h@W['l2.weight'].T+W['l2.bias'])
    return h@W['l3.weight'].T+W['l3.bias']
def tab(W,s):
    x=np.zeros((1024,68))
    for a in range(32):
        for b in range(32):
            x[a*32+b,a]=1;x[a*32+b,32+b]=1;x[a*32+b,64+s]=1
    return fwd(W,x).argmax(1).reshape(32,32)
W={n:load(n) for n in NAMES}
T=[tab(W,s) for s in range(4)]
np.save('T_now.npy',np.array(T))
np.set_printoptions(linewidth=250)
print('classes used',[np.bincount(t.ravel(),minlength=8)[:9].tolist() for t in T], 'max',[int(t.max()) for t in T])
# closed-form first guesses
fmax=np.percentile(T[0],15,axis=1).round().astype(int); gmax=np.percentile(T[0],15,axis=0).round().astype(int)
print('s0 max agree',(np.maximum.outer(fmax,gmax)==T[0]).mean(),fmax.tolist(),gmax.tolist())
fmin=np.percentile(T[3],85,axis=1).round().astype(int); gmin=np.percentile(T[3],85,axis=0).round().astype(int)
print('s3 min agree',(np.minimum.outer(fmin,gmin)==T[3]).mean(),fmin.tolist(),gmin.tolist())
t=T[1].astype(float); print('s1 rowmed',np.median(t,1).tolist()); print('s1 colmed',np.median(t,0).tolist())
t=T[2].astype(float); print('s2 rowmed',np.median(t,1).tolist()); print('s2 colmed',np.median(t,0).tolist())
for s in (1,2):
    print('skill',s)
    for r in T[s]: print(' '.join(str(v) for v in r))
```

