Closed-form means give 88-90% agreement with the table, within one class 99.9%, so the form looks right but the estimates are coarse. I will view the tables sorted by row and column order, and test a single non-saturated averaging step on three class scales; I will not run repeated fitting passes.
```python
from scipy.stats import norm
T=np.load('T_now.npy')
def binq(z):
    r=np.argsort(np.argsort(z.ravel(),kind='stable'),kind='stable')
    return (r*8//z.size).reshape(z.shape)
def tri_ppf(p):
    return np.where(p<.5,np.sqrt(2*p),2-np.sqrt(2*(1-p)))
scales={'linear':np.arange(8.),'normal':norm.ppf((np.arange(8)+.5)/8),'tri':tri_ppf((np.arange(8)+.5)/8)}
t=T[1]
for nm,q in scales.items():
    Q=q[t]; x=Q.mean(1); y=Q.mean(0)
    ok=(t>0)&(t<7)
    x1=np.array([(Q[a]-y)[ok[a]].mean() if ok[a].sum()>0 else x[a] for a in range(32)])
    y1=np.array([(Q[:,b]-x1)[ok[:,b]].mean() if ok[:,b].sum()>0 else y[b] for b in range(32)])
    P=binq(x1[:,None]+y1[None,:])
    print(nm,'mean-only',round((binq(x[:,None]+y[None,:])==t).mean(),4),'one step',round((P==t).mean(),4),'within1',round((abs(P-t)<=1).mean(),4))
    if nm=='tri': np.save('s1_x.npy',x1); np.save('s1_y.npy',y1)
x=np.load('s1_x.npy');y=np.load('s1_y.npy')
ra=np.argsort(x);rb=np.argsort(y)
print('s1 x sorted',np.round(x[ra],2).tolist());print('s1 y sorted',np.round(y[rb],2).tolist())
for r in t[ra][:,rb]: print(''.join(str(v) for v in r))
t=T[2]
ra=np.argsort(t.mean(1));rb=np.argsort(t.mean(0))
print('s2 sorted')
for r in t[ra][:,rb]: print(''.join(str(v) for v in r))
